export const PAPER_VIEWBOX = [0, 0, 29.973013, 3.508246] as const;
export const PAPER_ISLAND_CENTERS = [
	2.07756055, 4.54755746, 6.93935955, 9.55053749, 12.06779077, 14.60052813,
	17.15485275, 19.6329698, 22.10762931, 24.71596219, 27.13221285
];

export function paperGeometry(
	valveWidth = 1080,
	plenumWidths = 4,
	spongeWidths = 1
) {
	const height = Math.round((valveWidth * PAPER_VIEWBOX[3]) / PAPER_VIEWBOX[2]);
	const path = new Path2D(PAPER_PATH);
	const context = new OffscreenCanvas(1, 1).getContext('2d')!;
	const inside = (x: number, y: number) =>
		context.isPointInPath(
			path,
			((x + 0.5) * PAPER_VIEWBOX[2]) / valveWidth,
			((height - y - 0.5) * PAPER_VIEWBOX[3]) / height,
			'evenodd'
		);
	const valve = staggeredGeometry(valveWidth, height, inside, {
		left: 'open',
		right: 'open'
	});
	let area = 0;
	for (const cell of valve.cells) if (cell) area++;
	const meanWidth = area / valveWidth,
		plenum = Math.ceil(plenumWidths * meanWidth);
	if (
		!valve.cells.some((v, i) => !!v && i % valveWidth === 0) ||
		!valve.cells.some((v, i) => !!v && i % valveWidth === valveWidth - 1)
	)
		throw new Error('Sealed paper valve mouth');
	const grid = staggeredGeometry(
		valveWidth + 2 * plenum,
		height,
		(x, y) =>
			x < plenum ||
			x >= plenum + valveWidth ||
			!!valve.cells[y * valveWidth + x - plenum],
		{ left: 'open', right: 'open' }
	);
	const mouths = [0, valveWidth - 1].map((x) => {
		const ys = [];
		for (let y = 0; y < height; y++)
			if (valve.cells[y * valveWidth + x]) ys.push(y + 0.5);
		return ys.reduce((a, b) => a + b, 0) / ys.length;
	});
	return {
		grid,
		valve,
		valveWidth,
		height,
		meanWidth,
		plenum,
		buffer: Math.ceil(spongeWidths * meanWidth),
		cellsPerCm: valveWidth / 30,
		hydraulicDiameter: (valveWidth * 0.8) / 30,
		mouths
	};
}

/** Disturbance envelope centre and half-width (cells); the support is [centre - half, centre + half]. */
export function disturbanceBand(
	direction: number,
	g: { plenum: number; valveWidth: number; meanWidth: number },
	centerWidths = 2.25,
	halfWidthWidths = 0.7
) {
	return {
		center:
			direction > 0
				? g.plenum - centerWidths * g.meanWidth
				: g.plenum + g.valveWidth + centerWidths * g.meanWidth,
		halfWidth: halfWidthWidths * g.meanWidth
	};
}
